CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY,checksum text NOT NULL,applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts(id text PRIMARY KEY,issuer text NOT NULL,subject text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(issuer,subject));
CREATE TABLE devices(id text PRIMARY KEY,account_id text NOT NULL REFERENCES accounts(id),installation_id text NOT NULL,label text NOT NULL,credential_hash text NOT NULL,credential_generation integer NOT NULL DEFAULT 1,previous_credential_hash text,previous_credential_expires timestamptz,connection_epoch bigint NOT NULL DEFAULT 0,revoked boolean NOT NULL DEFAULT false,last_heartbeat timestamptz,agent_version text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX device_account ON devices(account_id);
CREATE TABLE pairing_intents(id text PRIMARY KEY,installation_id text NOT NULL,label text NOT NULL,credential_hash text NOT NULL,polling_hash text NOT NULL,code text NOT NULL,fingerprint text NOT NULL,state text NOT NULL DEFAULT 'pending',expires_at timestamptz NOT NULL,account_id text REFERENCES accounts(id),device_id text REFERENCES devices(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspace_summaries(id text PRIMARY KEY,account_id text NOT NULL REFERENCES accounts(id),device_id text NOT NULL REFERENCES devices(id),summary jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE operations(id text PRIMARY KEY,account_id text NOT NULL REFERENCES accounts(id),device_id text NOT NULL REFERENCES devices(id),workspace_id text NOT NULL,idempotency_key text NOT NULL,request_hash text NOT NULL,request jsonb NOT NULL,scopes jsonb NOT NULL,state text NOT NULL,device_operation_id text,dispatch_deadline timestamptz NOT NULL,result jsonb,result_expired boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(account_id,device_id,workspace_id,idempotency_key));
CREATE INDEX device_operation_alias ON operations(account_id,device_operation_id);
CREATE TABLE operation_events(seq bigserial PRIMARY KEY,operation_id text NOT NULL REFERENCES operations(id),event text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE dispatch_outbox(operation_id text PRIMARY KEY REFERENCES operations(id),attempts integer NOT NULL DEFAULT 0,last_attempt timestamptz,acknowledged boolean NOT NULL DEFAULT false);
CREATE TABLE result_deliveries(id text PRIMARY KEY,operation_id text NOT NULL REFERENCES operations(id),digest text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE result_chunks(delivery_id text NOT NULL,operation_id text NOT NULL REFERENCES operations(id),chunk_index integer NOT NULL,total integer NOT NULL,digest text NOT NULL,data text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(delivery_id,chunk_index));
CREATE TABLE operation_routes(id text PRIMARY KEY,account_id text NOT NULL REFERENCES accounts(id),device_id text NOT NULL REFERENCES devices(id),workspace_id text NOT NULL);
CREATE TABLE artifact_routes(id text PRIMARY KEY,account_id text NOT NULL REFERENCES accounts(id),device_id text NOT NULL REFERENCES devices(id),workspace_id text NOT NULL,mime_type text NOT NULL,bytes bigint NOT NULL,sha256 text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE owner_sessions(token_hash text PRIMARY KEY,account_id text REFERENCES accounts(id),state_hash text,pkce_verifier text,nonce text,csrf text NOT NULL,expires_at timestamptz NOT NULL,scopes jsonb NOT NULL DEFAULT '[]');
CREATE TABLE owner_settings(account_id text PRIMARY KEY REFERENCES accounts(id),retention_days integer NOT NULL DEFAULT 7 CHECK(retention_days BETWEEN 1 AND 30));
